import { Kbd } from '@absoluteui/components/kbd';

const list = document.createElement('ul');
document.body.append(list);
const shortcuts: [string, string][] = [['Save', 'Mod+S'], ['Command palette', 'Mod+Shift+P'], ['Close dialog', 'Esc'], ['Next row', 'ArrowDown']];
for (const [command, hotkey] of shortcuts) {
  const item = document.createElement('li');
  const keys = document.createElement('span');
  item.append(`${command}: `, keys);
  list.append(item);
  Kbd.create(keys, { hotkey });
}

import { Kbd } from '@absoluteui/components/kbd';

for (const platform of ['apple', 'other'] as const) {
  const line = document.createElement('p');
  const keys = document.createElement('span');
  line.append(`${platform === 'apple' ? 'macOS' : 'Windows and Linux'}: `, keys);
  document.body.append(line);
  Kbd.create(keys, { hotkey: 'Mod+Alt+Shift+K', platform });
}
